// Moves the files generated by `pwa-assets-generator` from assets/ into public/,
// leaving the source icon.svg in place. Run through `npm run icons`.
import { mkdirSync, readdirSync, renameSync } from 'node:fs';
import { join, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const from = join(root, 'assets');
const to = join(root, 'public');

mkdirSync(to, { recursive: true });
for (const file of readdirSync(from)) {
  if (file === 'icon.svg') continue;
  renameSync(join(from, file), join(to, file));
  console.log(`public/${file}`);
}
